140	    /**
141	     * The owner's age band, derived from {@code birthDate} measured against
142	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
143	     * 64, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
144	     * supplied, so the field is absent from the response.
145	     */
146	    @Transient
147	    public String getAgeBand() {
148	        if (this.birthDate == null || this.registrationDate == null) {
149	            return null;
150	        }
151	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
152	        if (years < 18) {
153	            return "MINOR";
154	        }
155	        if (years < 65) {
156	            return "ADULT";
157	        }
158	        return "SENIOR";
159	    }
