209	    /**
210	     * The owner's numeric membership level, derived from the fields assigned at
211	     * creation time. Starts at 1, adds 1 when an email is present, adds 1 when
212	     * {@code namesakeCount} is 0, and is capped at 3 (level 4 is reserved for tenure).
213	     */
214	    @Transient
215	    public int getMembershipLevel() {
216	        int level = 1;
217	        if (this.email != null && !this.email.isBlank()) {
218	            level++;
219	        }
220	        if (this.namesakeCount != null && this.namesakeCount == 0) {
221	            level++;
222	        }
223	        return Math.min(level, 3);
224	    }
225	
226	    /**
227	     * The owner's canonical region, preferring the postcode over the city.
228	     *
229	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
230	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
231	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
232	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
233	     * backs both the {@code locality} field and the {@code REGION} segment of the
234	     * {@code customerCode}, so the two always agree.
235	     */
236	    @Transient
237	    public String getRegion() {
238	        if (this.postcode != null && this.postcode.matches("[0-9]{4}")) {
239	            int value = Integer.parseInt(this.postcode);
240	            if (value >= 2000 && value <= 2099) {
241	                return "NSW";
242	            }
243	            if (value >= 3000 && value <= 3099) {
244	                return "VIC";
245	            }
246	            if (value >= 4000 && value <= 4099) {
247	                return "QLD";
248	            }
249	        }
250	        if ("Sydney".equals(this.city)) {
251	            return "NSW";
252	        }
253	        if ("Melbourne".equals(this.city)) {
254	            return "VIC";
255	        }
256	        if ("Brisbane".equals(this.city)) {
257	            return "QLD";
258	        }
259	        return "UNKNOWN";
260	    }
