271	    /**
272	     * The owner's derived duplicate-detection key: the normalized (E.164) telephone,
273	     * the email (or empty when absent) and the {@code householdId} (or empty when
274	     * absent), joined by {@code '|'}. Two owners are duplicates only when their whole
275	     * identity keys are equal.
276	     */
277	    @Transient
278	    public String getIdentityKey() {
279	        String tel = this.telephone == null ? "" : this.telephone;
280	        String mail = this.email == null ? "" : this.email;
281	        String household = this.householdId == null ? "" : this.householdId;
282	        return tel + "|" + mail + "|" + household;
283	    }
