1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Normalizes a telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
5	 * form: a leading {@code '+'} followed by 8 to 15 digits.
6	 *
7	 * <p>Rules:
8	 * <ul>
9	 *   <li>spaces, dashes and brackets are stripped;</li>
10	 *   <li>when the input already carries a leading {@code '+'} (a country code), it is kept
11	 *       and the remaining digits are used verbatim;</li>
12	 *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
13	 *       dropped from the national digits;</li>
14	 *   <li>the result must have 8 to 15 digits after the {@code '+'}, else it is not valid E.164;</li>
15	 *   <li>the national-number length must match the country code — {@code '+61'} requires exactly 9
16	 *       national digits and {@code '+1'} requires exactly 10; a wrong length is not valid.</li>
17	 * </ul>
18	 *
19	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
20	 * becomes {@code "+6421123456"}.
21	 */
22	public final class TelephoneE164 {
23	
24	    private TelephoneE164() {
25	    }
26	
27	    /**
28	     * Returns the E.164 form of {@code raw}, or {@code null} if it cannot form a valid E.164
29	     * number.
30	     */
31	    public static String normalize(String raw) {
32	        if (raw == null) {
33	            return null;
34	        }
35	        boolean hasCountryCode = raw.strip().startsWith("+");
36	        String digits = raw.replaceAll("\\D", "");
37	        String e164Digits;
38	        if (hasCountryCode) {
39	            e164Digits = digits;
40	        }
41	        else {
42	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
43	            e164Digits = "61" + national;
44	        }
45	        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
46	            return null;
47	        }
48	        if (!hasValidNationalLength(e164Digits)) {
49	            return null;
50	        }
51	        return "+" + e164Digits;
52	    }
53	
54	    /**
55	     * Checks the national-number length against the country code. {@code '+61'} requires exactly 9
56	     * national digits and {@code '+1'} requires exactly 10; other country codes are not constrained
57	     * here beyond the overall 8-to-15 E.164 length.
58	     */
59	    private static boolean hasValidNationalLength(String e164Digits) {
60	        if (e164Digits.startsWith("61")) {
61	            return e164Digits.length() - 2 == 9;
62	        }
63	        if (e164Digits.startsWith("1")) {
64	            return e164Digits.length() - 1 == 10;
65	        }
66	        return true;
67	    }
68	}
