13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber",
26	        expression = "java(String.format(\"%s-M%02d\", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "locality",
28	        expression = "java(owner.getRegion())")
29	    @Mapping(target = "checkDigit",
30	        expression = "java(luhn(owner.getCustomerCode()))")
31	    @Mapping(target = "bulkSignupWarning", ignore = true)
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * The single Luhn check digit (0-9) computed over the decimal digits contained in
36	     * {@code value}, right to left, doubling every second digit (starting with the
37	     * rightmost). Non-digit characters are ignored, so it works directly on a formatted
38	     * {@code customerCode} such as {@code 'NSW-A1B2C3D4'}.
39	     */
40	    default int luhn(String value) {
41	        int sum = 0;
42	        boolean dbl = true;
43	        for (int i = value.length() - 1; i >= 0; i--) {
44	            char c = value.charAt(i);
45	            if (c < '0' || c > '9') {
46	                continue;
47	            }
48	            int d = c - '0';
49	            if (dbl) {
50	                d *= 2;
51	                if (d > 9) {
52	                    d -= 9;
53	                }
54	            }
55	            sum += d;
56	            dbl = !dbl;
57	        }
58	        return (10 - (sum % 10)) % 10;
59	    }
60	
61	    Owner toOwner(OwnerDto ownerDto);
62	
63	    @Mapping(target = "id", ignore = true)
64	    @Mapping(target = "pets", ignore = true)
65	    Owner toOwner(OwnerFieldsDto ownerDto);
66	
67	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
68	
69	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
70	
71	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
72	        OwnerPageDto ownerPageDto = new OwnerPageDto();
73	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
74	        ownerPageDto.setPage(ownerPage.getNumber());
75	        ownerPageDto.setSize(ownerPage.getSize());
76	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
77	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
78	        return ownerPageDto;
79	    }
80	}
